import subprocess, sys, yaml, io

def get(kind, name, ns=None):
    cmd = ["kubectl", "get", kind, name, "-o", "yaml"]
    if ns: cmd[3:3] = ["-n", ns]
    return yaml.safe_load(subprocess.run(cmd, capture_output=True, text=True, check=True).stdout)

DROP_META = {"creationTimestamp","resourceVersion","uid","generation","managedFields",
             "selfLink","ownerReferences","finalizers"}
DROP_ANN = {"kubectl.kubernetes.io/last-applied-configuration",
            "deployment.kubernetes.io/revision",
            "field.cattle.io/publicEndpoints",
            "metallb.io/ip-allocated-from-pool",
            "kubectl.kubernetes.io/restartedAt",
            "pv.kubernetes.io/bind-completed",
            "pv.kubernetes.io/bound-by-controller",
            "volume.beta.kubernetes.io/storage-provisioner",
            "volume.kubernetes.io/storage-provisioner"}

def clean(o):
    o.pop("status", None)
    m = o.get("metadata", {})
    for k in list(m):
        if k in DROP_META: m.pop(k)
    ann = m.get("annotations", {})
    for k in list(ann):
        if k in DROP_ANN: ann.pop(k)
    if not ann: m.pop("annotations", None)
    return o

def emit(objs, path, header):
    docs = [clean(o) for o in objs]
    buf = io.StringIO()
    buf.write(header)
    for i, d in enumerate(docs):
        if i: buf.write("---\n")
        yaml.dump(d, buf, default_flow_style=False, sort_keys=False, width=100)
    open(path, "w").write(buf.getvalue())
    print("wrote", path, len(buf.getvalue()), "bytes")

if __name__ == "__main__":
    pass
